     */
    private static String addMultiply(String infixExpression) {
        int index = 0;
        int length = infixExpression.length();
        StringBuilder stringBuilder = null;
        for(int i = 0; i < length - 1; i++) {
            if(infixExpression.charAt(index) >= '0' && infixExpression.charAt(index) <= '9') {
                if((infixExpression.charAt(index + 1) >= 'a' && infixExpression.charAt(index + 1) <= 'z')
