class TreeNode {
    private String value;
    private TreeNode leftNode;
    private TreeNode rightNode;
    private int flag;

    public TreeNode() {}

    public TreeNode(String value) {
        this.value = value;
    }

    public void setValue(String value) {
        this.value = value;
    }

    public String getValue() {
        return value;
    }

